contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        c.depositsCount(); if (__ESBMC_reverted()) return;
        c.owner(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        assert((reverted && afterBal == beforeBal && afterDeposits == beforeDeposits) || (!reverted && afterBal == 0 && afterDeposits == beforeDeposits));
    }

    receive() external payable {}
}

